const fmtData = (iso) => DateTime.fromISO(String(iso), { zone: TZ }).setZone(TZ).setLocale('pt-BR').toFormat("cccc, dd/MM/yyyy 'às' HH:mm");

return $input.all().filter(i => i.json.numero).map(({ json: d }) => {
  const nome = d.nome ? d.nome.split(' ')[0] : '';
  const quando = d.inicio ? DateTime.fromISO(d.inicio).setZone(TZ).setLocale('pt-BR') : null;
  const local = d.modalidade === 'online' ? (d.link_reuniao ? `online, pelo link: ${d.link_reuniao}` : 'online')
    : d.modalidade === 'telefone' ? 'por telefone' : `no endereço ${d.endereco}`;
  let texto;
  if (d.tipo === 'lembrete_24h') {
    texto = `Olá${nome ? ', ' + nome : ''}! Aqui é a assistente virtual do ${d.escritorio}. Passando para lembrar da sua reunião com ${d.responsavel || 'nossa equipe'} ${quando.hasSame(DateTime.now().setZone(TZ), 'day') ? 'hoje' : quando.hasSame(DateTime.now().setZone(TZ).plus({ days: 1 }), 'day') ? 'amanhã' : quando.toFormat('cccc')} (${quando.toFormat("dd/MM")}) às ${quando.toFormat('HH:mm')}, ${local}.\n\nPode confirmar sua presença? Se precisar remarcar, é só me avisar por aqui.`;
  } else if (d.tipo === 'lembrete_1h') {
    texto = `${nome ? nome + ', s' : 'S'}ua reunião com ${d.responsavel || 'nossa equipe'} começa às ${quando.toFormat('HH:mm')}, ${local}. Até já!`;
  } else {
    texto = `Olá${nome ? ', ' + nome : ''}! Ficou alguma dúvida? Se quiser, posso verificar um horário para você conversar com um de nossos advogados.`;
  }
  return { json: { ...d, texto } };
});

