return $input.all().filter(i => i.json.whatsapp).map(({ json: r }) => {
  const itens = r.reunioes.map(a => {
    const h = DateTime.fromISO(a.inicio).setZone(TZ).toFormat('HH:mm');
    return `*${h}* - ${a.cliente} (${a.modalidade}${a.status === 'confirmado' ? ', confirmado ✅' : ''})\n   ${a.area || '-'} · wa.me/${a.whatsapp}${a.link ? '\n   ' + a.link : ''}${a.resumo ? '\n   _' + a.resumo.slice(0, 160) + '_' : ''}`;
  });
  const texto = `☀️ Bom dia, ${r.nome}! Sua agenda de hoje (${DateTime.now().setZone(TZ).toFormat('dd/MM')}):\n\n${itens.join('\n\n')}`
    + (Number(r.encaminhamentos_abertos) ? `\n\n📌 Você tem ${r.encaminhamentos_abertos} atendimento(s) encaminhado(s) em aberto.` : '');
  return { json: { instancia: r.instancia, numero: r.whatsapp, texto } };
});
